      },
      {
       "url": "name",
       "valueString": "Client's age is 2–5 years"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: Client's age is 2–5 years\n@pseudocode: 2 years ≤ Today's date − \"Date of birth\" ≤ 5 years\n@code: Client's age is 2–5 years-50\n@decision: IMMZ.D2.DT.Cholera.WC-rBS vaccine 3 doses: Whole cell-recombinant B subunit (WC-rBS) vaccine, 3-dose schedule for clients aged 2–5 years\n*/\ndefine \"Client's age is 2–5 years\":\n  Encounter.\"Current Patient Age In Years\" >= 2\n  and Encounter.\"Current Patient Age In Years\" <= 5"
      },
      {
       "url": "displaySequence",
       "valueInteger": 1
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZElements"
      },
      {
       "url": "name",
       "valueString": "Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/**\n * @dataElement All Doses Administered to Patient\n */\ndefine \"Doses Administered to Patient\":\n  [Immunization] I\n    where I.status = 'completed'\n    and I.isSubpotent is not true"
      },
      {
       "url": "displaySequence",
       "valueInteger": 2
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/**\n * @dataElement All Doses Administered to Patient\n */\ndefine \"Doses Administered to Patient\":\n  Elements.\"Doses Administered to Patient\" I\n    where I.occurrence.toInterval() same day or before Today"
      },
      {
       "url": "displaySequence",
       "valueInteger": 3
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTCholeraEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Cholera Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: Cholera containing Doses Administered to Patient\n*/\ndefine \"Cholera Doses Administered to Patient\":\n  Encounter.\"Doses Administered to Patient\" I\n  where\n    I.vaccineCode in Concepts.\"Cholera vaccines\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 4
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
