       "valueString": "Date of First Hib Dose"
      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: Date of First Hib Dose\n*/\ndefine \"Date of First Hib Dose\":\n  date from start of \"Hib Doses Administered to Patient\".earliest().occurrence.toInterval()"
      },
      {
       "url": "displaySequence",
       "valueInteger": 7
