       "url": "libraryName",
       "valueString": "IMMZD18SMeaslesLowTransmissionLogic"
      },
      {
       "url": "name",
       "valueString": "MCV2"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: MCV2\n@description: Provision of MCV2 from the primary series\n@trigger: MCV1 was administered\n@pseudo: Count of vaccines administered (where \"Vaccine type\" = \"Measles-containing vaccines\" and \"Type of dose\" = \"Primary series\") = 1\n@triggerDate: \"Date of birth\"\n*/\ndefine \"MCV2\":\n  not \"MCV2 was administered. The primary series has been completed\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 7
      }
     ],
