   "extension": [
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZElements"
      },
      {
       "url": "name",
       "valueString": "Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/**\n * @dataElement All Doses Administered to Patient\n */\ndefine \"Doses Administered to Patient\":\n  [Immunization] I\n    where I.status = 'completed'\n    and I.isSubpotent is not true"
      },
      {
       "url": "displaySequence",
       "valueInteger": 0
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/**\n * @dataElement All Doses Administered to Patient\n */\ndefine \"Doses Administered to Patient\":\n  Elements.\"Doses Administered to Patient\" I\n    where I.occurrence.toInterval() same day or before Today"
      },
      {
       "url": "displaySequence",
       "valueInteger": 1
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMumpsEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Mumps Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: Mumps containing Doses Administered to Patient\n*/\ndefine \"Mumps Doses Administered to Patient\":\n  Encounter.\"Doses Administered to Patient\" I\n  where\n    I.vaccineCode in Concepts.\"Mumps-containing vaccines\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 2
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMumpsEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Mumps Primary Series Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: Mumps containing Doses Administered to Patient that are in the Primary series\n*/\ndefine \"Mumps Primary Series Doses Administered to Patient\":\n  \"Mumps Doses Administered to Patient\".seriesPrimary()"
      },
      {
       "url": "displaySequence",
       "valueInteger": 3
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMumpsEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Number of Mumps Primary Series Doses Administered"
      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: Number of Mumps Primary Series doses\n*/\ndefine \"Number of Mumps Primary Series Doses Administered\":\n  Count(\"Mumps Primary Series Doses Administered to Patient\")"
      },
      {
       "url": "displaySequence",
       "valueInteger": 4
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMumpsEncounterElements"
      },
      {
       "url": "name",
       "valueString": "One mumps primary series dose was administered"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: One mumps primary series dose was administered\n@pseudocode: Count of vaccines administered (where \"Vaccine type\" = \"Mumps-containing vaccines\" and \"Type of dose\" = \"Primary series\") = 1\n@code: One mumps primary series dose was administered-125\n@decision: IMMZ.D2.DT.Mumps: 2-dose schedule (countries with mumps in schedule and low transmission of measles)\n*/\ndefine \"One mumps primary series dose was administered\":\n  \"Number of Mumps Primary Series Doses Administered\" = 1"
      },
      {
       "url": "displaySequence",
       "valueInteger": 5
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD18SMumpsLogic"
      },
      {
       "url": "name",
       "valueString": "First mumps dose from the primary series was administered"
      },
      {
       "url": "statement",
       "valueString": "/*\n@complete: First mumps dose from the primary series was administered\n@pseudocode: Count of vaccines administered (where \"Vaccine type\" = \"Mumps-containing vaccines\" and \"Type of dose\" = \"Primary series\") = 1\n*/\ndefine \"First mumps dose from the primary series was administered\":\n  Encounter.\"One mumps primary series dose was administered\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 6
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMumpsEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Two mumps primary series doses were administered"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: Two mumps primary series doses were administered\n@pseudocode: Count of vaccines administered (where \"Vaccine type\" = \"Mumps-containing vaccines\" and \"Type of dose\" = \"Primary series\") = 2\n@code: Two mumps primary series doses were administered-125\n@decision: IMMZ.D2.DT.Mumps: 2-dose schedule (countries with mumps in schedule and low transmission of measles)\n*/\ndefine \"Two mumps primary series doses were administered\":\n  \"Number of Mumps Primary Series Doses Administered\" = 2"
      },
      {
       "url": "displaySequence",
       "valueInteger": 7
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD18SMumpsLogic"
      },
      {
       "url": "name",
       "valueString": "Second mumps dose from the primary series was administered. The primary series has been completed"
      },
      {
       "url": "statement",
       "valueString": "/*\n@complete: Second mumps dose from the primary series was administered. The primary series has been completed\n@pseudocode: \"Completed the primary vaccination series\" = TRUE (where \"Vaccine type\" = \"Mumps-containing vaccines\")\"\n*/\ndefine \"Second mumps dose from the primary series was administered. The primary series has been completed\":\n  Encounter.\"Two mumps primary series doses were administered\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 8
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD18SMumpsLogic"
      },
      {
       "url": "name",
       "valueString": "Mumps dose 2"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Mumps dose 2\n@description: Provision of the mumps dose 2\n@trigger: First mumps dose from the primary series was administered\n@pseudo: Count of vaccines administered (where \"Vaccine type\" = \"Mumps-containing vaccines\" and \"Type of dose\" = \"Primary series\") = 1\n@triggerDate: \"Date and time of vaccination\" (where \"Vaccine type\" = \"Mumps-containing vaccines\")\n*/\ndefine \"Mumps dose 2\":\n  \"First mumps dose from the primary series was administered\"\n  and not \"Second mumps dose from the primary series was administered. The primary series has been completed\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 9
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMumpsEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Date of Latest Mumps Dose"
      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: Date of Latest Mumps Dose\n*/\ndefine \"Date of Latest Mumps Dose\":\n  date from start of \"Mumps Doses Administered to Patient\".mostRecent().occurrence.toInterval()"
      },
      {
       "url": "displaySequence",
       "valueInteger": 10
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD18SMumpsLogic"
      },
      {
       "url": "name",
       "valueString": "Mumps dose 2 Due Date"
      },
      {
       "url": "statement",
       "valueString": "/*\n@dynamicValue: Mumps dose 2 Due Date\n@pseudocode: \"Date and time of vaccination\" (where \"Vaccine type\" = \"Mumps-containing vaccines\") + 1 month\n*/\ndefine \"Mumps dose 2 Due Date\":\n  if \"Mumps dose 2\" then Encounter.\"Date of Latest Mumps Dose\" + 1 month\n  else null"
      },
      {
       "url": "displaySequence",
       "valueInteger": 11
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD18SMumpsLogic"
      },
      {
       "url": "name",
       "valueString": "Mumps dose 2 Overdue"
      },
      {
       "url": "statement",
       "valueString": "/*\n@dynamicValue: Mumps dose 2 Overdue\n@pseudocode: \"Date of birth\" + 6 years\n*/\ndefine \"Mumps dose 2 Overdue\":\n  if \"Mumps dose 2\" then Patient.birthDate + 6 years\n  else null"
      },
      {
       "url": "displaySequence",
       "valueInteger": 12
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD18SMumpsLogic"
      },
      {
       "url": "name",
       "valueString": "Mumps dose 2 Create"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Mumps dose 2 Create\n@create: The age of administration of the second dose may range from the second year of life to age at school entry (about 6 years of age). The minimum interval between the first and the second doses is 1 month.\n*/\ndefine \"Mumps dose 2 Create\":\n  if \"Mumps dose 2\"\n  then 'The age of administration of the second dose may range from the second year of life to age at school entry (about 6 years of age). The minimum interval between the first and the second doses is 1 month.' + '\nDue Date: ' + ToString(\"Mumps dose 2 Due Date\") + '\nOverdue: ' + ToString(\"Mumps dose 2 Overdue\")\n  else ''"
      },
      {
       "url": "displaySequence",
       "valueInteger": 13
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMumpsEncounterElements"
      },
      {
       "url": "name",
       "valueString": "No mumps primary series doses were administered"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: No mumps primary series doses were administered\n@pseudocode: Count of vaccines administered (where \"Vaccine type\" = \"Mumps-containing vaccines\" and \"Type of dose\" = \"Primary series\") = 0\n@code: No mumps primary series doses were administered-125\n@decision: IMMZ.D2.DT.Mumps: 2-dose schedule (countries with mumps in schedule and low transmission of measles)\n*/\ndefine \"No mumps primary series doses were administered\":\n  \"Number of Mumps Primary Series Doses Administered\" = 0"
      },
      {
       "url": "displaySequence",
       "valueInteger": 14
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
