      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: Number of Rabies Primary Series doses\n*/\ndefine \"Number of Rabies Primary Series Doses Administered\":\n  Count(\"Rabies Primary Series Doses Administered to Patient\")"
