      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: Rotavirus containing Doses Administered to Patient\n*/\ndefine \"Rotavirus Doses Administered to Patient\":\n  Encounter.\"Doses Administered to Patient\" I\n  where\n    I.vaccineCode in Concepts.\"Rotavirus vaccines\""
