       "url": "statement",
       "valueString": "/*\n@dynamicValue: Yellow fever dose 1 Due Date\n@pseudocode: \"Date of birth\" + 9 months\n*/\ndefine \"Yellow fever dose 1 Due Date\":\n  if \"Yellow fever dose 1\" then Patient.birthDate + 9 months\n  else null"
