       "url": "statement",
       "valueString": "/*\n@dynamicValue: Yellow fever dose 1 Overdue\n@pseudocode: \"Date of birth\" + 12 months\n*/\ndefine \"Yellow fever dose 1 Overdue\":\n  if \"Yellow fever dose 1\" then Patient.birthDate + 12 months\n  else null"
