      {
       "url": "name",
       "valueString": "Client's age is more than or equal to 1 year"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: Client's age is more than or equal to 1 year\n@pseudocode: Today's date − \"Date of birth\" ≥ 1 year\n@code: Client's age is more than or equal to 1 year-39\n@decision: IMMZ.D2.DT.Cholera.WC vaccines: Whole-cell (WC) vaccines schedule\n*/\ndefine \"Client's age is more than or equal to 1 year\":\n  Encounter.\"Current Patient Age In Years\" >= 1"
      },
