    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTCholeraEncounterElements"
      },
      {
       "url": "name",
       "valueString": "The latest cholera dose was administered more than 14 days ago and less than 3 years ago"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: The latest cholera dose was administered more than 14 days ago and less than 3 years ago\n@pseudocode: 14 days <= Today's date − latest \"Date and time of vaccination\" (where \"Vaccine type\" = \"Cholera vaccines\") <= 3 years\n@code: The latest cholera dose was administered more than 14 days ago and less than 3 years ago-118\n@decision: IMMZ.D2.DT.Cholera.WC vaccines: Whole-cell (WC) vaccines schedule\n*/\ndefine \"The latest cholera dose was administered more than 14 days ago and less than 3 years ago\":\n  \"The latest cholera dose was administered more than 14 days ago\"\n  and \"The latest cholera dose was administered less than 3 years ago\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 36
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTCholeraWCVaccinesLogic"
      },
      {
       "url": "name",
       "valueString": "Client is due for cholera booster dose"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is due for cholera booster dose\n@pseudocode: \"Immunization recommendation status\" = \"Due\"\n*/\ndefine \"Client is due for cholera booster dose\":\n  Encounter.\"Client's age is more than or equal to 1 year\"\n    and Encounter.\"Two cholera primary series doses were administered\"\n    and Encounter.\"At least one booster series dose was administered\"\n    and Encounter.\"Dose number of the latest dose is one\"\n    and Encounter.\"The latest cholera dose was administered more than 14 days ago and less than 3 years ago\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 37
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTCholeraWCVaccinesLogic"
      },
      {
       "url": "name",
       "valueString": "Client is due for cholera booster dose Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is due for cholera booster dose Guidance\n@guidance: Should vaccinate client with cholera booster dose as the booster series is not completed and the latest cholera dose was administered more than 14 days ago.\nCheck for contraindications.\n*/\ndefine \"Client is due for cholera booster dose Guidance\":\n  'Should vaccinate client with cholera booster dose as the booster series is not completed and the latest cholera dose was administered more than 14 days ago.\nCheck for contraindications.'"
      },
      {
       "url": "displaySequence",
       "valueInteger": 38
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTCholeraEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Dose number of the latest dose is two"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: Dose number of the latest dose is two\n@pseudocode: Latest \"Dose number\" (where \"Vaccine type\" = \"Cholera vaccines\") = 2\n@code: Dose number of the latest dose is two-68\n@decision: IMMZ.D2.DT.Cholera.WC vaccines: Whole-cell (WC) vaccines schedule\n*/\ndefine \"Dose number of the latest dose is two\":\n  \"Cholera Doses Administered to Patient\".mostRecent().getDose('2') is not null"
      },
      {
       "url": "displaySequence",
       "valueInteger": 39
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
