    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTCholeraWCVaccinesLogic"
      },
      {
       "url": "name",
       "valueString": "Booster series is complete"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Booster series is complete\n@pseudocode: \"Completed the booster series\" (where \"Vaccine type\" = \"Cholera vaccines\") = TRUE\n*/\ndefine \"Booster series is complete\":\n  Encounter.\"Client's age is more than or equal to 1 year\"\n    and Encounter.\"Two cholera primary series doses were administered\"\n    and Encounter.\"At least one booster series dose was administered\"\n    and Encounter.\"Dose number of the latest dose is two\"\n    and Encounter.\"The latest cholera dose was administered less than 3 years ago\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 40
      }
     ],
