    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTCholeraWCVaccinesLogic"
      },
      {
       "url": "name",
       "valueString": "Booster series is complete Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Booster series is complete Guidance\n@guidance: Should not vaccinate client with cholera dose as the booster series for cholera was completed less than 3 years ago. \nCheck for any vaccines due and inform the caregiver of when to come back for the next booster series.\n*/\ndefine \"Booster series is complete Guidance\":\n  'Should not vaccinate client with cholera dose as the booster series for cholera was completed less than 3 years ago. \nCheck for any vaccines due and inform the caregiver of when to come back for the next booster series.'"
      },
      {
       "url": "displaySequence",
       "valueInteger": 41
      }
