    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTCholeraWCVaccinesLogic"
      },
      {
       "url": "name",
       "valueString": "Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@dynamicValue: Guidance\n*/\ndefine \"Guidance\":\n  case \n    when \"Client is not due for cholera vaccination\" then \"Client is not due for cholera vaccination Guidance\"\n    when \"Client is due for cholera vaccination\" then \"Client is due for cholera vaccination Guidance\"\n    when \"Primary series is complete. Client is not due for cholera booster dose\" then \"Primary series is complete. Client is not due for cholera booster dose Guidance\"\n    when \"Primary series is complete. Client is due for cholera booster dose\" then \"Primary series is complete. Client is due for cholera booster dose Guidance\"\n    when \"Client is not due for cholera booster dose\" then \"Client is not due for cholera booster dose Guidance\"\n    when \"Client is due for cholera booster dose\" then \"Client is due for cholera booster dose Guidance\"\n    when \"Booster series is complete\" then \"Booster series is complete Guidance\" \n    else ''\n  end"
      },
