       "valueString": "IMMZD2DTHib3DosesWithBoosterDoseLogic"
      },
      {
       "url": "name",
       "valueString": "Hib immunization schedule is complete Case 2"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Hib immunization schedule is complete Case 2\n@pseudocode: \"Immunization recommendation status\" = \"Complete\"\n*/\ndefine \"Hib immunization schedule is complete Case 2\":\n  Encounter.\"Three Hib primary series doses were administered\"\n    and Encounter.\"One Hib booster dose was administered\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 37
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTHib3DosesWithBoosterDoseLogic"
      },
      {
       "url": "name",
       "valueString": "Hib immunization schedule is complete"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Hib immunization schedule is complete\n@pseudocode: \"Immunization recommendation status\" = \"Complete\"\n\"Completed the primary vaccination series\" = TRUE (where \"Vaccine type\" = \"Hib-containing vaccines\")\n*/\ndefine \"Hib immunization schedule is complete\":\n  \"Hib immunization schedule is complete Case 1\"\n    or \"Hib immunization schedule is complete Case 2\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 38
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTHib3DosesWithBoosterDoseLogic"
      },
      {
       "url": "name",
       "valueString": "Hib immunization schedule is complete Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Hib immunization schedule is complete Guidance\n@guidance = Hib immunization schedule is complete as client's age was more than 1 year when first Hib dose was administered.\nCheck for any other vaccines due.\n@guidance = Hib immunization schedule is complete. Three Hib primary series doses and one booster dose have been administered. \nCheck for any vaccines due.\n*/\ndefine \"Hib immunization schedule is complete Guidance\":\n  case\n    when \"Hib immunization schedule is complete Case 1\" then 'Hib immunization schedule is complete as client\\'s age was more than 1 year when first Hib dose was administered.\nCheck for any other vaccines due.'\n    when \"Hib immunization schedule is complete Case 2\" then 'Hib immunization schedule is complete. Three Hib primary series doses and one booster dose have been administered. \nCheck for any vaccines due.'\n    else ''\n  end"
      },
      {
       "url": "displaySequence",
       "valueInteger": 39
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTHibEncounterElements"
      },
      {
       "url": "name",
       "valueString": "No Hib booster doses were administered"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: No Hib booster doses were administered\n@pseudocode: Count of vaccines administered where \"Vaccine type\" = \"Hib-containing vaccines\" and \"Type of dose\"\" = \"Booster dose\") = 0\n@code: No Hib booster doses were administered-121\n@decision: IMMZ.D2.DT.Hib.3 doses with booster dose: 3 primary doses with a booster dose (3p+1)\n@decision: IMMZ.D2.DT.Hib.2 doses with booster dose: 2 primary doses with a booster dose (2p+1)\n*/\ndefine \"No Hib booster doses were administered\":\n  \"Number of Hib Booster Series Doses Administered\" = 0"
      },
