      },
      {
       "url": "name",
       "valueString": "Primary series is complete. Client is not due for Hib booster dose"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Primary series is complete. Client is not due for Hib booster dose\n@pseudocode: \"Immunization recommendation status\" = \"Not due\"\n\"Completed the primary vaccination series\" = TRUE (where \"Vaccine type\" = \"Hib-containing vaccines\")\n*/\ndefine \"Primary series is complete. Client is not due for Hib booster dose\":\n  Encounter.\"Three Hib primary series doses were administered\"\n    and Encounter.\"No Hib booster doses were administered\"\n    and Encounter.\"Client's age is between 6 weeks and 5 years\"\n    and Encounter.\"The latest Hib dose was administered less than 6 months ago\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 42
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
