       "url": "libraryName",
       "valueString": "IMMZD2DTHib3DosesWithBoosterDoseLogic"
      },
      {
       "url": "name",
       "valueString": "Primary series is complete. Client is not due for Hib booster dose Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Primary series is complete. Client is not due for Hib booster dose Guidance\n@guidance: Should not vaccinate client with Hib booster dose as the latest Hib dose was administered less than 6 months ago. Hib primary series is complete. \nCheck for any other vaccines due and inform the caregiver of when to come back for booster dose.\n*/\ndefine \"Primary series is complete. Client is not due for Hib booster dose Guidance\":\n  'Should not vaccinate client with Hib booster dose as the latest Hib dose was administered less than 6 months ago. Hib primary series is complete. \nCheck for any other vaccines due and inform the caregiver of when to come back for booster dose.'"
      },
      {
       "url": "displaySequence",
       "valueInteger": 43
      }
