      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMeaslesEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Client's age is less than 12 months"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: Client's age is less than 12 months\n@pseudocode: Today's date − \"Date of birth\" < 12 months\n@code: Client's age is less than 12 months-42\n@decision: IMMZ.D2.DT.Measles.Low transmission: Countries with low levels of measles transmission (countries that provide first dose of measles-containing vaccine (MCV) at 12 months and second dose of MCV at 15 months)\n*/\ndefine \"Client's age is less than 12 months\":\n  Encounter.\"Current Patient Age In Months\" < 12"
      },
      {
       "url": "displaySequence",
       "valueInteger": 1
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
