       "url": "libraryName",
       "valueString": "IMMZEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Date of Latest Live Attenuated Vaccine"
      },
      {
       "url": "statement",
       "valueString": "/*\n@dataElement Date and time of last live attenuated vaccine\n*/\ndefine \"Date of Latest Live Attenuated Vaccine\":\n  date from start of \"Live Attenuated Vaccines\".mostRecent().occurrence.toInterval()"
      },
      {
       "url": "displaySequence",
       "valueInteger": 12
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Live vaccine was administered in the last 4 weeks"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: Live vaccine was administered in the last 4 weeks\n@pseudocode: Today's date − latest \"Date and time of vaccination\" (where \"Live vaccine\" = TRUE) < 4 weeks\n*/\ndefine \"Live vaccine was administered in the last 4 weeks\":\n\t\"Date of Latest Live Attenuated Vaccine\" is not null \n    and duration in weeks between \"Date of Latest Live Attenuated Vaccine\" and Today < 4"
      },
      {
       "url": "displaySequence",
       "valueInteger": 13
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMeaslesEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Live vaccine was administered in the last 4 weeks"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: Live vaccine was administered in the last 4 weeks\n@pseudocode: Today's date − latest \"Date and time of vaccination\" (where \"Live vaccine\" = TRUE) < 4 weeks\n@code: Live vaccine was administered in the last 4 weeks-92\n@decision: IMMZ.D2.DT.Measles.Ongoing transmission: Countries with ongoing transmission in which the risk of measles mortality remains high (countries that provide first dose of measles-containing vaccine (MCV) at 9 months and second dose of MCV at 15 months)\n@decision: IMMZ.D2.DT.Measles.Low transmission: Countries with low levels of measles transmission (countries that provide first dose of measles-containing vaccine (MCV) at 12 months and second dose of MCV at 15 months)\n@decision: IMMZ.D2.DT.Measles.MCV dose 0: Measles-containing vaccine dose 0 (MCV0) administration\n*/\ndefine \"Live vaccine was administered in the last 4 weeks\":\n  Encounter.\"Live vaccine was administered in the last 4 weeks\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 14
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMeaslesLowTransmissionLogic"
      },
      {
       "url": "name",
       "valueString": "Client is not due for MCV1 Case 2"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for MCV1 Case 2\n@pseudocode: \"Immunization recommendation status\" = \"Not due\"\n*/\ndefine \"Client is not due for MCV1 Case 2\":\n  Encounter.\"No measles primary series doses were administered\"\n    and Encounter.\"Client's age is more than or equal to 12 months\"\n    and Encounter.\"Live vaccine was administered in the last 4 weeks\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 15
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMeaslesLowTransmissionLogic"
      },
      {
       "url": "name",
       "valueString": "Client is not due for MCV1"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for MCV1\n@pseudocode: \"Immunization recommendation status\" = \"Not due\"\n*/\ndefine \"Client is not due for MCV1\":\n  \"Client is not due for MCV1 Case 1\"\n    or \"Client is not due for MCV1 Case 2\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 16
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMeaslesLowTransmissionLogic"
      },
      {
       "url": "name",
       "valueString": "Client is not due for MCV1 Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for MCV1 Guidance\n@guidance = Should not vaccinate client with MCV1 as client's age is less than 12 months.\nCheck for any vaccines due and inform the caregiver of when to come back for MCV1.\n@guidance = Should not vaccinate client with MCV1 as live vaccine was administered in the past 4 weeks.\nCheck for any vaccines due and inform the caregiver of when to come back for MCV1.\n*/\ndefine \"Client is not due for MCV1 Guidance\":\n  case\n    when \"Client is not due for MCV1 Case 1\" then 'Should not vaccinate client with MCV1 as client\\'s age is less than 12 months.\nCheck for any vaccines due and inform the caregiver of when to come back for MCV1.'\n    when \"Client is not due for MCV1 Case 2\" then 'Should not vaccinate client with MCV1 as live vaccine was administered in the past 4 weeks.\nCheck for any vaccines due and inform the caregiver of when to come back for MCV1.'\n    else ''\n  end"
