      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: MCV Dose 0 Doses Administered to Patient\n*/\ndefine \"MCV Dose 0 Doses Administered to Patient\":\n  \"MCV Doses Administered to Patient\".seriesDose0()"
