      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for MCV0 Case 3\n@pseudocode: \"Immunization recommendation status\" = \"Not due\"\n*/\ndefine \"Client is not due for MCV0 Case 3\":\n  Encounter.\"Client's age is more than or equal to 9 months\""
