      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for MCV0 Case 4\n@pseudocode: \"Immunization recommendation status\" = \"Not due\"\n*/\ndefine \"Client is not due for MCV0 Case 4\":\n  Encounter.\"MCV0 was administered\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 19
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMeaslesMCVDose0Logic"
      },
      {
       "url": "name",
       "valueString": "Client is not due for MCV0"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for MCV0\n@pseudocode: \"Immunization recommendation status\" = \"Not due\"\n*/\ndefine \"Client is not due for MCV0\":\n  \"Client is not due for MCV0 Case 1\"\n    or \"Client is not due for MCV0 Case 2\"\n    or \"Client is not due for MCV0 Case 3\"\n    or \"Client is not due for MCV0 Case 4\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 20
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMeaslesMCVDose0Logic"
      },
      {
       "url": "name",
       "valueString": "Client is not due for MCV0 Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for MCV0 Guidance\n@guidance = Should not vaccinate client with MCV0 as client's age is less than 6 months. Check for any vaccines due and inform the caregiver of when to come back for MCV0.\n@guidance = Should not vaccinate client with MCV0 as live vaccine was administered in the past 4 weeks. Check for any vaccines due and inform the caregiver of when to come back for MCV0.\n@guidance = Should not vaccinate client with MCV0 as client's age is more than 9 months.\nCheck measles routine immunization schedule.\n@guidance = MCV0 was administered.\nCheck measles routine immunization schedule.\n*/\ndefine \"Client is not due for MCV0 Guidance\":\n  case\n    when \"Client is not due for MCV0 Case 1\" then 'Should not vaccinate client with MCV0 as client\\'s age is less than 6 months. Check for any vaccines due and inform the caregiver of when to come back for MCV0.'\n    when \"Client is not due for MCV0 Case 2\" then 'Should not vaccinate client with MCV0 as live vaccine was administered in the past 4 weeks. Check for any vaccines due and inform the caregiver of when to come back for MCV0.'\n    when \"Client is not due for MCV0 Case 3\" then 'Should not vaccinate client with MCV0 as client\\'s age is more than 9 months.\nCheck measles routine immunization schedule.'\n    when \"Client is not due for MCV0 Case 4\" then 'MCV0 was administered.\nCheck measles routine immunization schedule.'\n    else ''\n  end"
      },
      {
       "url": "displaySequence",
       "valueInteger": 21
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
