       "valueString": "IMMZEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Current Patient Age In Months"
      },
      {
       "url": "statement",
       "valueString": "/** \n * @dataElement Patient age in months\n */\ndefine \"Current Patient Age In Months\":\n  AgeInMonthsAt(Today)"
      },
      {
       "url": "displaySequence",
       "valueInteger": 0
      }
