       "url": "libraryName",
       "valueString": "IMMZD2DTMumpsEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Client's age is less than 12 months"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: Client's age is less than 12 months\n@pseudocode: Today's date − \"Date of birth\" < 12 months\n@code: Client's age is less than 12 months-42\n@decision: IMMZ.D2.DT.Mumps: 2-dose schedule (countries with mumps in schedule and low transmission of measles)\n*/\ndefine \"Client's age is less than 12 months\":\n  Encounter.\"Current Patient Age In Months\" < 12"
      },
      {
       "url": "displaySequence",
       "valueInteger": 1
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMumpsLogic"
      },
      {
       "url": "name",
       "valueString": "Client is not due for mumps vaccination Case 1"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for mumps vaccination Case 1\n@pseudocode: \"Immunization recommendation status\" = \"Not due\"\n*/\ndefine \"Client is not due for mumps vaccination Case 1\":\n  Encounter.\"Client's age is less than 12 months\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 2
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZElements"
      },
      {
       "url": "name",
       "valueString": "Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/**\n * @dataElement All Doses Administered to Patient\n */\ndefine \"Doses Administered to Patient\":\n  [Immunization] I\n    where I.status = 'completed'\n    and I.isSubpotent is not true"
      },
      {
       "url": "displaySequence",
       "valueInteger": 3
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/**\n * @dataElement All Doses Administered to Patient\n */\ndefine \"Doses Administered to Patient\":\n  Elements.\"Doses Administered to Patient\" I\n    where I.occurrence.toInterval() same day or before Today"
      },
      {
       "url": "displaySequence",
       "valueInteger": 4
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMumpsEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Mumps Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: Mumps containing Doses Administered to Patient\n*/\ndefine \"Mumps Doses Administered to Patient\":\n  Encounter.\"Doses Administered to Patient\" I\n  where\n    I.vaccineCode in Concepts.\"Mumps-containing vaccines\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 5
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTMumpsEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Mumps Primary Series Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: Mumps containing Doses Administered to Patient that are in the Primary series\n*/\ndefine \"Mumps Primary Series Doses Administered to Patient\":\n  \"Mumps Doses Administered to Patient\".seriesPrimary()"
      },
      {
       "url": "displaySequence",
       "valueInteger": 6
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
