      {
       "url": "name",
       "valueString": "Client is due for IPV vaccination"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is due for IPV vaccination\n@pseudocode: \"Immunization recommendation status\" = \"Due\" (where \"Type of poliovirus dose\" = \"IPV\")\n*/\ndefine \"Client is due for IPV vaccination\":\n  \"Client is due for IPV vaccination Case 1\"\n    or \"Client is due for IPV vaccination Case 2\"\n    or \"Client is due for IPV vaccination Case 3\"\n    or \"Client is due for IPV vaccination Case 4\"\n    or \"Client is due for IPV vaccination Case 5\"\n    or \"Client is due for IPV vaccination Case 6\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 76
      }
