      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: Polio Dose 0 Doses Administered to Patient\n*/\ndefine \"Polio Dose 0 Doses Administered to Patient\":\n  \"Polio Doses Administered to Patient\".seriesDose0()"
