       "url": "name",
       "valueString": "Client is due for the bOPV birth dose"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is due for the bOPV birth dose\n@pseudocode: \"Immunization recommendation status\" = \"Due\" (where \"Type of poliovirus dose\" = \"bOPV\")\n*/\ndefine \"Client is due for the bOPV birth dose\":\n  Encounter.\"bOPV birth dose (a zero dose) was not administered\"\n    and Encounter.\"Client's age is less than 1 week\""
      },
