      },
      {
       "url": "name",
       "valueString": "Client is due for the bOPV birth dose Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is due for the bOPV birth dose Guidance\n@guidance: Should vaccinate client with bOPV birth dose (a zero dose) as poliovirus birth dose was not administered and client's age is less than 1 week. Check for contraindications.\n*/\ndefine \"Client is due for the bOPV birth dose Guidance\":\n  'Should vaccinate client with bOPV birth dose (a zero dose) as poliovirus birth dose was not administered and client\\'s age is less than 1 week. Check for contraindications.'"
      },
