     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Live vaccine was administered in the last 4 weeks"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: Live vaccine was administered in the last 4 weeks\n@pseudocode: Today's date − latest \"Date and time of vaccination\" (where \"Live vaccine\" = TRUE) < 4 weeks\n*/\ndefine \"Live vaccine was administered in the last 4 weeks\":\n\t\"Date of Latest Live Attenuated Vaccine\" is not null \n    and duration in weeks between \"Date of Latest Live Attenuated Vaccine\" and Today < 4"
      },
      {
       "url": "displaySequence",
       "valueInteger": 13
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTRubellaEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Live vaccine was administered in the last the 4 weeks"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: Live vaccine was administered in the last the 4 weeks\n@pseudocode: Today's date − latest \"Date and time of vaccination\" (where \"Live vaccine\" = TRUE) < 4 weeks\n@code: Live vaccine was administered in the last the 4 weeks-92\n@decision: IMMZ.D2.DT.Rubella.Low incidence: Countries with low incidence of rubella\n*/\ndefine \"Live vaccine was administered in the last the 4 weeks\":\n  Encounter.\"Live vaccine was administered in the last 4 weeks\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 14
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTRubellaLowIncidenceLogic"
      },
      {
       "url": "name",
       "valueString": "Client is not due for rubella vaccination Case 2"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for rubella vaccination Case 2\n@pseudocode: \"Immunization recommendation status\" = \"Not due\"\n*/\ndefine \"Client is not due for rubella vaccination Case 2\":\n  Encounter.\"No rubella primary series dose was administered\"\n    and Encounter.\"Client's age is more than or equal to 12 months\"\n    and Encounter.\"Live vaccine was administered in the last the 4 weeks\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 15
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTRubellaLowIncidenceLogic"
      },
      {
       "url": "name",
       "valueString": "Client is not due for rubella vaccination"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for rubella vaccination\n@pseudocode: \"Immunization recommendation status\" = \"Not due\"\n*/\ndefine \"Client is not due for rubella vaccination\":\n  \"Client is not due for rubella vaccination Case 1\"\n    or \"Client is not due for rubella vaccination Case 2\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 16
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTRubellaLowIncidenceLogic"
      },
      {
       "url": "name",
       "valueString": "Client is not due for rubella vaccination Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for rubella vaccination Guidance\n@guidance = Should not vaccinate client with rubella dose. \nCheck for any vaccines due and inform the caregiver of when to come back for the first dose.\n@guidance = Should not vaccinate client with rubella dose as live vaccine was administered in the last 4 weeks. \nCheck for any other vaccines due.\n*/\ndefine \"Client is not due for rubella vaccination Guidance\":\n  case\n    when \"Client is not due for rubella vaccination Case 1\" then 'Should not vaccinate client with rubella dose. \nCheck for any vaccines due and inform the caregiver of when to come back for the first dose.'\n    when \"Client is not due for rubella vaccination Case 2\" then 'Should not vaccinate client with rubella dose as live vaccine was administered in the last 4 weeks. \nCheck for any other vaccines due.'\n    else ''\n  end"
      },
      {
       "url": "displaySequence",
       "valueInteger": 17
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZEncounterElements"
      },
      {
       "url": "name",
       "valueString": "No live vaccine was administered in the last 4 weeks"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: No live vaccine was administered in the last 4 weeks\n@pseudocode: Today's date − latest \"Date and time of vaccination\" (where \"Live vaccine\" = TRUE) ≥ 4 weeks\n*/\ndefine \"No live vaccine was administered in the last 4 weeks\":\n  not(\"Live vaccine was administered in the last 4 weeks\")"
      },
      {
       "url": "displaySequence",
       "valueInteger": 18
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
