       "url": "libraryName",
       "valueString": "IMMZD2DTSeasonalinfluenzaSeasonalInfluenzaLogic"
      },
      {
       "url": "name",
       "valueString": "The primary series is complete. Client is due for seasonal influenza annual dose Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: The primary series is complete. Client is due for seasonal influenza annual dose Guidance\n@guidance = Should vaccinate client with annual dose as the latest seasonal influenza dose was administered more than 1 year ago. \nCheck for contraindications.\n@guidance = Should vaccinate client with annual dose as latest seasonal influenza dose was administered more than 1 year ago. \nCheck for contraindications.\n*/\ndefine \"The primary series is complete. Client is due for seasonal influenza annual dose Guidance\":\n  case\n    when \"The primary series is complete. Client is due for seasonal influenza annual dose Case 1\" then 'Should vaccinate client with annual dose as the latest seasonal influenza dose was administered more than 1 year ago. \nCheck for contraindications.'\n    when \"The primary series is complete. Client is due for seasonal influenza annual dose Case 2\" then 'Should vaccinate client with annual dose as latest seasonal influenza dose was administered more than 1 year ago. \nCheck for contraindications.'\n    else ''\n  end"
      },
      {
       "url": "displaySequence",
       "valueInteger": 34
      }
     ],
