       "url": "name",
       "valueString": "Client is due for TBE vaccination"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is due for TBE vaccination\n@pseudocode: \"Immunization recommendation status\" = \"Due\"\n*/\ndefine \"Client is due for TBE vaccination\":\n  \"Client is due for TBE vaccination Case 1\"\n    or \"Client is due for TBE vaccination Case 2\"\n    or \"Client is due for TBE vaccination Case 3\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 31
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTTBEEncepurLogic"
      },
      {
       "url": "name",
       "valueString": "Client is due for TBE vaccination Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is due for TBE vaccination Guidance\n@guidance = Should vaccinate client with first TBE dose as no TBE doses have been administered and client's age is more than 1 year. \nCheck for contraindications.\n@guidance = Should vaccinate client with second TBE dose as the latest dose was administered more than 1 month ago. \nCheck for contraindications.\n@guidance = Should vaccinate client with third TBE dose as the latest dose was administered more than 9 months ago.\nCheck for contraindications.\n*/\ndefine \"Client is due for TBE vaccination Guidance\":\n  case\n    when \"Client is due for TBE vaccination Case 1\" then 'Should vaccinate client with first TBE dose as no TBE doses have been administered and client\\'s age is more than 1 year. \nCheck for contraindications.'\n    when \"Client is due for TBE vaccination Case 2\" then 'Should vaccinate client with second TBE dose as the latest dose was administered more than 1 month ago. \nCheck for contraindications.'\n    when \"Client is due for TBE vaccination Case 3\" then 'Should vaccinate client with third TBE dose as the latest dose was administered more than 9 months ago.\nCheck for contraindications.'\n    else ''\n  end"
      },
      {
       "url": "displaySequence",
       "valueInteger": 32
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTTBEEncepurLogic"
      },
      {
       "url": "name",
       "valueString": "The primary series is complete. Client is not due for TBE booster dose"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: The primary series is complete. Client is not due for TBE booster dose\n@pseudocode: \"Immunization recommendation status\" = \"Not due\"\n\"Completed the primary vaccination series\" = TRUE (where \"Vaccine type\" = \"TBE vaccines\")\n*/\ndefine \"The primary series is complete. Client is not due for TBE booster dose\":\n  Encounter.\"Three TBE primary series doses were administered\"\n    and Encounter.\"No TBE booster dose was administered\"\n    and Encounter.\"The latest TBE dose was administered less than 3 years ago\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 33
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTTBEEncepurLogic"
      },
      {
       "url": "name",
       "valueString": "The primary series is complete. Client is not due for TBE booster dose Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: The primary series is complete. Client is not due for TBE booster dose Guidance\n@guidance: Should not vaccinate client with TBE booster dose as the latest TBE dose was administered less than 3 years ago. \nCheck for any vaccines due and inform the caregiver of when to come back for the booster dose.\n*/\ndefine \"The primary series is complete. Client is not due for TBE booster dose Guidance\":\n  'Should not vaccinate client with TBE booster dose as the latest TBE dose was administered less than 3 years ago. \nCheck for any vaccines due and inform the caregiver of when to come back for the booster dose.'"
      },
