    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTTyphoidViPSLogic"
      },
      {
       "url": "name",
       "valueString": "Client is not due for Typhoid vaccination"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for Typhoid vaccination\n@pseudocode: \"Immunization recommendation status\" = \"Not due\"\n*/\ndefine \"Client is not due for Typhoid vaccination\":\n  Encounter.\"Client's age is less than 2 years\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 2
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTTyphoidViPSLogic"
      },
      {
       "url": "name",
       "valueString": "Client is not due for Typhoid vaccination Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Client is not due for Typhoid vaccination Guidance\n@guidance: Should not vaccinate client with typhoid dose as client's age is less than 2 years.\nCheck for any other vaccines due and inform the caregiver of when to come back for the first dose.\n*/\ndefine \"Client is not due for Typhoid vaccination Guidance\":\n  'Should not vaccinate client with typhoid dose as client\\'s age is less than 2 years.\nCheck for any other vaccines due and inform the caregiver of when to come back for the first dose.'"
      },
      {
       "url": "displaySequence",
       "valueInteger": 3
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZElements"
      },
      {
       "url": "name",
       "valueString": "Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/**\n * @dataElement All Doses Administered to Patient\n */\ndefine \"Doses Administered to Patient\":\n  [Immunization] I\n    where I.status = 'completed'\n    and I.isSubpotent is not true"
      },
      {
       "url": "displaySequence",
       "valueInteger": 4
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/**\n * @dataElement All Doses Administered to Patient\n */\ndefine \"Doses Administered to Patient\":\n  Elements.\"Doses Administered to Patient\" I\n    where I.occurrence.toInterval() same day or before Today"
      },
      {
       "url": "displaySequence",
       "valueInteger": 5
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD2DTTyphoidEncounterElements"
      },
      {
       "url": "name",
       "valueString": "Typhoid Doses Administered to Patient"
      },
      {
       "url": "statement",
       "valueString": "/*\n@internal: Typhoid containing Doses Administered to Patient\n*/\ndefine \"Typhoid Doses Administered to Patient\":\n  Encounter.\"Doses Administered to Patient\" I\n  where\n    I.vaccineCode in Concepts.\"Typhoid vaccines\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 6
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
    {
     "extension": [
