       "valueString": "/*\n@internal: Date of Latest Typhoid Dose\n*/\ndefine \"Date of Latest Typhoid Dose\":\n  date from start of \"Typhoid Doses Administered to Patient\".mostRecent().occurrence.toInterval()"
