      {
       "url": "name",
       "valueString": "Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@dynamicValue: Guidance\n*/\ndefine \"Guidance\":\n  case \n    when \"Hepatitis B vaccination could be contraindicated. Clinical judgement is required. Create a clinical note.\" then \"Hepatitis B vaccination could be contraindicated. Clinical judgement is required. Create a clinical note. Guidance\" \n    else ''\n  end"
      },
