      {
       "url": "name",
       "valueString": "Meningococcal vaccination could be contraindicated. Clinical judgement is required. Create a clinical note"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Meningococcal vaccination could be contraindicated. Clinical judgement is required. Create a clinical note\n@pseudocode: \"Immunization recommendation status\" (where \"Type of meningococcal dose\" = \"Polysaccharide vaccine\") = \"Further evaluation needed\"\n*/\ndefine \"Meningococcal vaccination could be contraindicated. Clinical judgement is required. Create a clinical note\":\n  Encounter.\"The client has history of severe allergic reactions\""
      },
      {
       "url": "displaySequence",
