      {
       "url": "name",
       "valueString": "Meningococcal vaccination could be contraindicated. Clinical judgement is required. Create a clinical note Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Meningococcal vaccination could be contraindicated. Clinical judgement is required. Create a clinical note Guidance\n@guidance: Do not vaccinate client with meningococcal if client has history of severe allergic reaction to any component of the meningococcal vaccine.\n*/\ndefine \"Meningococcal vaccination could be contraindicated. Clinical judgement is required. Create a clinical note Guidance\":\n  'Do not vaccinate client with meningococcal if client has history of severe allergic reaction to any component of the meningococcal vaccine.'"
      },
