      {
       "url": "libraryName",
       "valueString": "IMMZD5DTRabiesEncounterElements"
      },
      {
       "url": "name",
       "valueString": "The client has history of severe allergic reactions"
      },
      {
       "url": "statement",
       "valueString": "/*\n@input: The client has history of severe allergic reactions\n@pseudocode: \"Potential contraindications\" = \"Severe allergic reactions\"\n@code: The client has history of severe allergic reactions-59\n@decision: IMMZ.D5.DT.Rabies contraindications\n*/\ndefine \"The client has history of severe allergic reactions\":\n  Encounter.\"The client has history of severe allergic reactions\""
      },
