     "extension": [
      {
       "url": "libraryName",
       "valueString": "IMMZD5DTRabiesContraindicationsLogic"
      },
      {
       "url": "name",
       "valueString": "Clinical judgement is required. Create a clinical note"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Clinical judgement is required. Create a clinical note\n@pseudocode: \"Immunization recommendation status\" = \"Further evaluation needed\"\n*/\ndefine \"Clinical judgement is required. Create a clinical note\":\n  Encounter.\"The client has history of severe allergic reactions\""
      },
      {
       "url": "displaySequence",
       "valueInteger": 7
      }
     ],
     "url": "http://hl7.org/fhir/StructureDefinition/cqf-logicDefinition"
    },
