       "url": "libraryName",
       "valueString": "IMMZD5DTRabiesContraindicationsLogic"
      },
      {
       "url": "name",
       "valueString": "Clinical judgement is required. Create a clinical note Guidance"
      },
      {
       "url": "statement",
       "valueString": "/*\n@output: Clinical judgement is required. Create a clinical note Guidance\n@guidance: Check if the client has a history of severe hypersensitivity to any of the components or to excipients listed by the vaccine manufacturer. If so, provide an alternative rabies vaccine product for PreP.\n*/\ndefine \"Clinical judgement is required. Create a clinical note Guidance\":\n  'Check if the client has a history of severe hypersensitivity to any of the components or to excipients listed by the vaccine manufacturer. If so, provide an alternative rabies vaccine product for PreP.'"
      },
      {
       "url": "displaySequence",
       "valueInteger": 8
      }
